const CACHE='ghifar-shell-v17',FILES=['/','/index.html','/styles.css','/enterprise.css','/operations.css','/app.js','/enterprise.js','/operations.js','/offline.js','/core.js','/restaurant.js','/qr.js','/growth.js','/growth-ui.js','/growth.css','/spreadsheet.js','/categories.js','/business.js','/business-ui.js','/business.css','/manifest.webmanifest','/app-icon.svg'];
self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(FILES)));self.skipWaiting()});
self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('ghifar-shell-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',e=>{const u=new URL(e.request.url);if(e.request.method!=='GET'||u.origin!==self.location.origin||u.pathname.startsWith('/api/')||/signin|signout|callback/.test(u.pathname))return;if(e.request.mode==='navigate'){e.respondWith(fetch(e.request).catch(()=>caches.match('/index.html')));return}if(FILES.includes(u.pathname))e.respondWith(fetch(e.request).then(r=>{if(r.ok){const copy=r.clone();caches.open(CACHE).then(c=>c.put(u.pathname,copy))}return r}).catch(()=>caches.match(u.pathname)))});
